import com.argument.resulttrial.ResultTrialService;
import com.argument.exporttrial.*;
import com.argument.version.*;
import com.argument.version.local.*;
import com.argument.version.port.VersionIdentity;
import com.argument.support.ResearchFixture;
import com.argument.common.exception.BusinessException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.SpyBean;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
@SpringBootTest @ActiveProfiles("test") @Import(ResearchFixture.class)
class CorrectionAndResultTrialTest {
 @Autowired CorrectionTrialService service;@Autowired ResearchFixture research;@Autowired LocalFixtureLoader loader;@Autowired JdbcTemplate jdbc;@Autowired VersionIdentity identity;@Autowired ObjectMapper mapper;@Autowired FinalReviewService finals;@Autowired AdjudicationService adjudication;@Autowired AdjudicationRepository sessions;@Autowired ResultTrialService results;@Autowired ExportTrialService exports;@Autowired ExportTrialWorker worker;@Autowired LocalAnnotationDependencies data;@Autowired com.argument.segmentationtrial.SegmentationTrialService segmentation;
 @SpyBean LocalFinalReviewDependencies deps;
 @BeforeEach void setup()throws Exception{reset(deps);clean();loader.run(null);}
 @AfterEach void after(){reset(deps);clean();}
 void clean(){for(String t:List.of("trial_correction_rounds","trial_segmentation_records","trial_downloads","trial_files","trial_data_events","trial_exports","trial_export_receipts","trial_final_commitments","trial_audit_events","final_review_transitions","final_annotation_versions","adjudication_transitions","adjudication_returned_versions","adjudication_decisions","adjudication_items","adjudication_sessions","annotation_mutation_receipts","annotation_version_snapshots","annotation_versions","annotation_case_counters","local_annotation_dependencies"))jdbc.update("DELETE FROM "+t);}
 VersionIdentity.Actor arbiter(){return identity.authenticate("Bearer dev-arbiter-zhao");}
 ObjectNode rejected(){var s=research.create(false,false);finals.transition(arbiter(),s.path("version").path("id").asText(),VersionJson.uuid(),2,"FV04",mapper.createObjectNode().put("reason","需要修正关系"));return finals.read(arbiter(),s.path("version").path("id").asText());}
 ObjectNode round(ObjectNode snapshot,String key){return service.create(arbiter(),snapshot.path("version").path("id").asText(),key,3,mapper.createObjectNode().put("reason","重新核查全部命题与关系"));}
 void complete(String id,boolean removeRelation){var session=sessions.session(id,false);for(var item:sessions.items(id,"PROPOSITION")){var cmd=mapper.createObjectNode().put("reason","本轮重新确认");if("AGREEMENT".equals(item.path("conflictType").asText()))cmd.put("action","CONFIRM_AGREEMENT");else{String object=item.path("candidateElementIds").get(0).asText();cmd.put("action","ADOPT_VERSION").put("sourceObjectId",object);for(var source:adjudication.snapshots(session))for(var e:source.path("elements"))if(object.equals(e.path("id").asText()))cmd.put("sourceVersionId",source.path("version").path("id").asText());}adjudication.decideLocalProposition(arbiter(),item.path("id").asText(),VersionJson.uuid(),1,cmd);}adjudication.complete(arbiter(),id,VersionJson.uuid(),sessions.session(id,false).path("recordVersion").asInt(),mapper.createObjectNode().put("confirmed",true),"PROPOSITION");for(var item:sessions.items(id,"RELATION")){var cmd=mapper.createObjectNode().put("reason","补正：移除缺少依据的关系").put("action",removeRelation?"DELETE":"ADOPT_VERSION");if(!removeRelation){String object=item.path("candidateRelationIds").get(0).asText();cmd.put("sourceObjectId",object);for(var source:adjudication.snapshots(session))for(var r:source.path("relations"))if(object.equals(r.path("id").asText()))cmd.put("sourceVersionId",source.path("version").path("id").asText());}adjudication.decideRelation(arbiter(),item.path("id").asText(),VersionJson.uuid(),1,cmd);}adjudication.complete(arbiter(),id,VersionJson.uuid(),sessions.session(id,false).path("recordVersion").asInt(),mapper.createObjectNode().put("confirmed",true),"RELATION");}
 @Test void correctionIsIndependentAndActuallyChangesFinalContent(){var old=rejected();String id=old.path("version").path("id").asText(),digest=FinalReviewService.contentDigest(old),key=VersionJson.uuid();var round=round(old,key);assertThat(round(old,key)).isEqualTo(round);String sid=round.path("sessionId").asText();assertThat(sid).isNotEqualTo(old.path("version").path("sessionId").asText());assertThatThrownBy(()->finals.transition(arbiter(),id,VersionJson.uuid(),4,"FV03",mapper.createObjectNode().put("action","SUBMIT"))).isInstanceOf(BusinessException.class).hasMessageContaining("补正");complete(sid,true);var created=finals.create(arbiter(),sid,VersionJson.uuid(),2);var next=finals.read(arbiter(),created.path("id").asText());assertThat(next.path("relations")).isEmpty();assertThat(old.path("relations")).hasSize(1);assertThat(FinalReviewService.contentDigest(finals.read(arbiter(),id))).isEqualTo(digest);reset(deps);assertThat(finals.assessment(next,sessions.session(sid,false)).path("formalReady").asBoolean()).isFalse();}
 @Test void sameDecisionsWithNewIdsAndReasonsDoNotCountAsSubstantiveCorrection(){var old=rejected();var round=round(old,VersionJson.uuid());String sid=round.path("sessionId").asText();complete(sid,false);assertThatThrownBy(()->finals.create(arbiter(),sid,VersionJson.uuid(),2)).isInstanceOf(BusinessException.class).hasMessageContaining("实质决定");}
 @Test void committedResultsCannotBeCorrectedOrReadByAnnotator(){var snapshot=research.create(true);String id=snapshot.path("version").path("id").asText();assertThatThrownBy(()->service.create(arbiter(),id,VersionJson.uuid(),4,mapper.createObjectNode().put("reason","越权修改"))).isInstanceOf(BusinessException.class);assertThatThrownBy(()->results.read(identity.authenticate("Bearer dev-annotator-chen"),id)).isInstanceOf(BusinessException.class);}
 @Test void resultCountsUseActualDynamicDictionariesAndScopeBeforePaging(){var snapshot=research.create(true);String id=snapshot.path("version").path("id").asText();var creator=identity.authenticate("Bearer dev-creator-li");var detail=results.read(creator,id);assertThat(detail.path("labelDistribution")).hasSize(15);long elements=0;for(var r:detail.path("labelDistribution"))elements+=r.path("count").asLong();assertThat(elements).isEqualTo(2);assertThat(detail.path("agreement").path("reproducible").asBoolean()).isFalse();assertThat(results.list(creator,null,null,1,20).path("total").asInt()).isEqualTo(1);var cmd=mapper.createObjectNode().put("format","JSON");cmd.putArray("finalVersionIds").add(id);cmd.putArray("include");var record=exports.create(creator,VersionJson.uuid(),cmd);worker.processOne();exports.ticket(creator,record.path("id").asText(),false,VersionJson.uuid(),mapper.createObjectNode().put("purpose","成果核验"),VersionJson.uuid());var events=results.exportEvents(creator,record.path("id").asText());assertThat(events.path("items")).hasSize(3);assertThat(events.toString()).doesNotContain("downloadToken","tokenDigest","storageKey");var task=data.find("task",null,null).get(0);task.put("ownerUserId",VersionJson.uuid());data.replace("task",task);assertThat(results.list(creator,null,null,1,20).path("total").asInt()).isZero();assertThatThrownBy(()->results.exportEvents(creator,record.path("id").asText())).isInstanceOf(BusinessException.class);}
 @Test void realSegmentationFlowsThroughFinalCommitResultAndFrozenExport(){String c=ResearchFixture.CASE;var body=mapper.createObjectNode();var boundaries=body.putArray("boundaries");boundaries.addObject().put("startOffset",5).put("endOffset",20);boundaries.addObject().put("startOffset",20).put("endOffset",39);for(String token:List.of("dev-annotator-chen","dev-annotator-liu"))segmentation.submit(identity.authenticate("Bearer "+token),c,VersionJson.uuid(),body);var calc=segmentation.calculate(arbiter(),c,VersionJson.uuid(),mapper.createObjectNode());var confirm=mapper.createObjectNode().put("calculationId",calc.path("id").asText()).put("reason","两名标注员共同确认");confirm.set("unifiedBoundaries",boundaries.deepCopy());var cp=segmentation.confirm(arbiter(),c,VersionJson.uuid(),confirm);int i=0;for(String token:List.of("dev-annotator-chen","dev-annotator-liu")){String draft=List.of("f67848e1-a06d-4600-8454-19055e720d2c","ef21c243-05a2-4837-92b4-d56f3fb77639").get(i++);segmentation.bind(identity.authenticate("Bearer "+token),c,VersionJson.uuid(),1,mapper.createObjectNode().put("draftId",draft).put("checkpointId",cp.path("id").asText()));}var snapshot=research.create(true);String id=snapshot.path("version").path("id").asText();var creator=identity.authenticate("Bearer dev-creator-li");assertThat(results.read(creator,id).path("agreement").path("reproducible").asBoolean()).isTrue();var descriptor=results.reannotationSource(creator,id);assertThat(descriptor.path("sourceTaskId").asText()).isEqualTo("f102c523-b4ed-4323-81d3-0c564c4141a0");assertThat(descriptor.path("sourceFinalVersionId").asText()).isEqualTo(id);var cmd=mapper.createObjectNode().put("format","JSON");cmd.putArray("finalVersionIds").add(id);cmd.putArray("include");var r=exports.create(creator,VersionJson.uuid(),cmd);worker.processOne();assertThat(exports.read(creator,r.path("id").asText()).path("status").asText()).isEqualTo("COMPLETED");}
}
